        for it in spec.get("contains") or []:
            if not any(_subset(it, x) for x in items):
                mism.append(f"table {alias}: expected an item matching {json.dumps(it)[:200]}; has {json.dumps(items)[:300]}")
        for it in spec.get("not_contains") or []:
